  "bar.res.made": "a year · the stores hold a year of use",
  "bar.hint.gdp": "Everything the country produces in a year, with its growth beside it. It grows with trade, industry and research, and falls with war, sanctions and lost land.",
  "bar.hint.budget": "The treasury's income minus its spending over a year. Income follows the economy and taxes, spending the army, industry and welfare; a deficit is covered by debt or reserves.",
  "bar.hint.debt": "What the state owes, and its share of GDP. It grows with every deficit, and the interest rises as the debt grows against GDP.",
  "bar.hint.reserves": "The central bank's currency and gold. They pay for imports and defend the currency; when they run out, both are at risk.",
  "bar.hint.inflation": "How fast prices rise in a year. It climbs with printed money, shortages and war, and falls with a tight budget.",
  "bar.hint.troops": "Soldiers under arms. After the slash, how many more can be called up: that depends on the population and the conscription law.",
  "bar.hint.unrest": "How restless the country is, from 0 to 100: discontent, protests, rumours. It rises with war, poverty, prices and unpopular decisions, and falls with concessions and order; from 65 the government can be overthrown.",
  "bar.hint.crises": "Troubles already under way: debt, prices, shortages, the street. Each grows worse until it is dealt with.",
  "bar.hint.resources": "Strategic resources: how many the country has enough of, imports or lacks. A shortage hits industry and the army.",
