  "supply.cause.austerity": "little social spending",
  "supply.why.warEconomy": "The army budget takes more than 8% of GDP: every point past it takes one and a half points of the goods people can buy. Industry spending, policies and imports win back up to three fifths of that over months; only a smaller army budget brings back all of it.",
  "supply.why.austerity": "Social spending below the era's usual share of GDP: homes and hospitals go short. A larger social line brings them back.",
  "supply.cause.research": "research",
  "supply.cause.industry": "industry investment",
  "supply.why.industry": "Industry spending past the era's usual share of GDP builds consumer factories and works the mines harder over months, as do industry and infrastructure policies; spending below it runs them down. The money comes out of the budget like any other line.",
  "supply.why.imports": "Goods and fuel bought abroad while trade is open. Goods are paid from the reserves and stop as they near half the era's usual level.",
  "supply.hint.goods": "What raises goods: a smaller army budget; industry spending past the era's usual share and industry or infrastructure policies (built over months); a lead in industry research; imports while trade is open and the reserves last.",
  "supply.hint.energy": "What raises energy and the stores: own output past need refills the stores; industry spending, industry and infrastructure policies and a lead in industry research make mines and wells give up to 30% more over a decade; contracts refill the stores of what they bring.",
