  "means.readyHint": "How much of the army is mobilised and fights at full weight: the side that chose the moment starts readier, and both reach full weight over the era's mobilisation.",
  "means.reach": "Supply",
  "means.reachHint": "How much of the strength reaches the front from home: it falls past a thousand kilometres over land, and across a sea it takes ships and a sea the enemy's fleet does not close.",
  "means.will": "Will",
  "means.willHint": "The will to fight, 0–100: support for the war at home – an invaded people rallies whatever it thinks of its government – worn down by war-weariness. An army fights at full weight only with the will.",
  "means.weary": "Weariness",
  "means.wearyHint": "War-weariness, 0–100: losses against the population and the years of war. Democracies feel losses most; people defending their own land bear more.",
  "means.rear": "Partisans",
  "means.rearHint": "Troops tied down by resistance in occupied land, % of the army: partisans also kill soldiers and cut supply near the front.",
  "means.limited": "The attackers fight for limited aims",
  "means.limitedHint": "Short of the means – ships for a distant war, a trained army, the will at home – the attackers fight only for the land next to their own.",
  "means.estimate": "Intelligence estimate, to the nearest ten",
