  "cabinet.loyalty.rising": "Loyalty rising",
  "cabinet.loyalty.falling": "Loyalty falling",
  "cabinet.loyalty.steady": "Loyalty steady",
  "cabinet.loyalty.hint": "Orders and laws for their causes, favours and promotions raise it; going against their causes, humiliations and dismissing their allies lower it.",
  "cabinet.rivals": "Rivals: {names}.",
  "cabinet.rival.post": "both aim higher",
  "cabinet.rival.causes": "their causes clash",
  "cabinet.act.favour": "Grant a favour",
  "cabinet.act.favour.hint": "Honours, money, a dacha: loyalty grows, rivals resent it. A plotter may take it and change nothing. Once a turn.",
  "cabinet.act.post": "A seat at the top table",
  "cabinet.act.post.hint": "Deputy premier, a seat on the inner council: stills their ambition and blunts their faction's plot; the ambitious resent it. Only once.",
  "cabinet.act.move": "Reshuffle",
  "cabinet.act.move.hint": "Swap posts with another minister: a move up pleases, a move down humiliates, and the new post brings new causes. Once a turn.",
  "cabinet.act.swapWith": "Swap with",
  "cabinet.act.swap": "Swap",
  "cabinet.act.dismiss": "Dismiss",
  "cabinet.act.dismiss.hint": "Their faction takes offence, their rivals are pleased; the post stays empty until you appoint someone.",
  "cabinet.act.investigate": "Investigate",
  "cabinet.act.investigate.hint": "The intelligence service looks into the faction. Finding nothing proves nothing, and a service in the faction covers it up. Once a turn.",
  "cabinet.act.purge": "Purge",
  "cabinet.act.purge.hint": "Removes the whole faction. Costs the elites' and the security services' loyalty, stability and, in a democracy, votes. Once a turn.",
  "cabinet.why.this-turn": "Already done this turn.",
  "cabinet.why.once": "Already given once.",
  "cabinet.why.no-service": "There is no head of intelligence.",
  "cabinet.why.other": "Not possible now.",
  "cabinet.plots": "What intelligence reports",
  "cabinet.plots.none": "No word of plots in the cabinet.",
  "cabinet.plot.unknownFaction": "Unknown plotters",
  "cabinet.plot.known": "Confirmed",
  "cabinet.plot.rumoured": "Rumour",
  "cabinet.plot.stage.talk": "talk",
  "cabinet.plot.stage.organised": "organised",
  "cabinet.plot.stage.ready": "ready to strike",
  "cabinet.plot.known.hint": "The service is sure of it. It is listed among the plots in politics, where you can hold talks with the plotters or order it foiled.",
  "cabinet.plot.rumoured.hint": "Only a rumour, and it may blame the wrong people: investigate before you purge anyone.",
