  "bar.hint.gdp": "Всё, что страна производит за год, и его рост рядом. Растёт от торговли, промышленности и науки, падает от войны, санкций и потери земель.",
  "bar.hint.budget": "Доходы казны минус расходы за год. Доходы зависят от экономики и налогов, расходы – от армии, промышленности и соцсферы; дефицит покрывают долг или резервы.",
  "bar.hint.debt": "Сколько государство должно, и доля этого долга в ВВП. Растёт с каждым дефицитом, а проценты тем выше, чем больше долг к ВВП.",
  "bar.hint.reserves": "Валюта и золото центрального банка. На них оплачивают импорт и защищают курс; кончатся – под угрозой и то, и другое.",
  "bar.hint.inflation": "Насколько дорожают цены за год. Растёт от печати денег, нехватки товаров и войны, падает при твёрдом бюджете.",
  "bar.hint.troops": "Солдаты под ружьём. После косой черты – сколько ещё можно призвать: это зависит от населения и закона о призыве.",
  "bar.hint.unrest": "Насколько неспокойна страна, от 0 до 100: недовольство, протесты, слухи. Растёт от войны, бедности, цен и непопулярных решений, падает от уступок и порядка; с 65 правительство могут свергнуть.",
