  "supply.why.industry": "Расходы на промышленность сверх обычной для эпохи доли ВВП за несколько месяцев строят фабрики товаров и поднимают добычу, как и политики развития промышленности и инфраструктуры; расходы ниже нормы их сокращают. Деньги идут из бюджета, как любая статья.",
  "supply.why.imports": "Товары и топливо, купленные за границей, пока торговля открыта. Товары оплачиваются из резервов и прекращаются, когда резервы подходят к половине обычного для эпохи уровня.",
  "supply.hint.goods": "Что поднимает товары: меньший военный бюджет; расходы на промышленность сверх обычной для эпохи доли и политики развития промышленности или инфраструктуры (строятся месяцами); опережение в промышленных исследованиях; импорт, пока торговля открыта и хватает резервов.",
  "supply.hint.energy": "Что поднимает энергию и запасы: своя добыча сверх потребности пополняет запасы; расходы на промышленность, политики развития промышленности и инфраструктуры и опережение в промышленных исследованиях за десятилетие дают до 30% больше добычи; контракты пополняют запасы того, что везут.",
