  "portraits.about": "Лідерів і міністрів, а також письменників і мислителів, яких цитує очікування ходу, написано олією за зображеннями з вільною ліцензією: суспільне надбання, CC0, CC BY, CC BY-SA, відкриті ліцензії урядів Великої Британії, Індії та Кореї і Європарламенту, Free Art License, або без відомих обмежень авторського права, з Wikimedia Commons. Портрет зберігає ліцензію своєї фотографії, окремо від коду гри під AGPL-3.0. Хто не має вільної фотографії, і кожна нова людина – силует.",
