  "supply.why.warEconomy": "Армія забирає понад 8% ВВП: кожен пункт понад це відбирає півтора пункту товарів у населення. Вкладення в промисловість, політики й імпорт за кілька місяців повернуть до трьох п'ятих; усе поверне лише менший військовий бюджет.",
