  "supply.why.imports": "Товари й паливо, куплені за кордоном, поки торгівля відкрита. Товари оплачуються з резервів і припиняються, коли резерви підходять до половини звичного для епохи рівня.",
  "supply.hint.goods": "Що піднімає товари: менший військовий бюджет; видатки на промисловість понад звичну для епохи частку й політики розвитку промисловості чи інфраструктури (будуються місяцями); випередження в промислових дослідженнях; імпорт, поки торгівля відкрита й вистачає резервів.",
  "supply.hint.energy": "Що піднімає енергію й запаси: власний видобуток понад потребу поповнює запаси; видатки на промисловість, політики розвитку промисловості й інфраструктури та випередження в промислових дослідженнях за десятиліття дають до 30% більше видобутку; контракти поповнюють запаси того, що везуть.",
