  "politics.desc.campaign": "Мітинги, плакати й ефір для партії по всій країні. Підтримка зростає, якщо час на її боці.",
  "politics.act.renew": "Оновити керівництво",
  "politics.desc.renew": "Замінити стару гвардію партії новими обличчями. Освіжає образ; відставлені затаять образу.",
  "politics.order.renew": "Оновити керівництво партії «{party}»: замінити стару гвардію новими обличчями",
  "politics.desc.support": "Гроші, ефір і доступ до влади для партії. Її підтримка зростає; виборці можуть вважати її маріонеткою влади.",
  "politics.act.negotiate": "Домовитися",
  "politics.desc.negotiate": "Виторгувати їхні голоси з конкретного питання без коаліції. Дешевше за коаліцію, але ціну призначають вони.",
  "politics.order.negotiate": "Домовитися з партією «{party}» про голоси в парламенті",
  "politics.act.leave": "Розірвати коаліцію",
  "politics.desc.leave": "Вивести партнера з уряду. Розв'язує руки, але ви втрачаєте їхні місця.",
  "politics.order.leave": "Розірвати коаліцію з партією «{party}» і відправити її міністрів у відставку",
  "politics.act.coalition": "Покликати в коаліцію",
  "politics.desc.coalition": "Запропонувати міністерства й поступки за їхні голоси. Їхні місця працюють на уряд; їхні вимоги стають вашими.",
  "politics.order.coalition": "Запросити партію «{party}» до правлячої коаліції: запропонувати міністерства й поступки за голоси",
  "politics.act.poach": "Переманити депутатів",
  "politics.desc.poach": "Перетягнути їхніх депутатів посадами, грошима чи тиском. Місця без виборів; скандал, якщо спливе.",
  "politics.order.poach": "Переманити депутатів партії «{party}» на бік уряду",
  "politics.act.smear": "Дискредитувати",
  "politics.desc.smear": "Компромат, скандали й ворожа преса проти партії та її лідера. Підтримка падає, якщо звинувачення прилипнуть.",
  "politics.order.smear": "Провести кампанію з дискредитації партії «{party}» та її лідера",
  "politics.desc.suppress": "Обшуки, тиск, арешти активістів. Послаблює партію, але радикалізує прихильників і підвищує напругу.",
  "politics.act.arrest": "Заарештувати лідера",
  "politics.desc.arrest": "Порушити справу проти лідера партії. Обезголовить її – або зробить мученика.",
  "politics.order.arrest": "Заарештувати лідера партії «{party}»",
  "politics.desc.ban": "Оголосити партію поза законом. Вона йде в підпілля, її місця порожніють, а прихильники виходять на вулиці.",
  "politics.desc.legalise": "Повернути партію в легальну політику. Заспокоює її прихильників; вона боротиметься за голоси.",
