  "tour.ideas.body": "Наприклад, такі накази:",
  "tour.idea.1914.1": "Відправити послів до всіх великих держав і з'ясувати, хто стане на наш бік, якщо почнеться війна",
  "tour.idea.1914.2": "Привести армію в готовність біля найнебезпечнішого кордону, без загальної мобілізації",
  "tour.idea.1914.3": "Закупити зерно й вугілля в резерв на випадок тривалої кризи",
  "tour.idea.1939.1": "Скликати воєнний кабінет і вирішити наш курс у війні, що почалася сьогодні",
  "tour.idea.1939.2": "Перевести промисловість на воєнні рейки й запасти нафту",
  "tour.idea.1939.3": "Запропонувати сусідам пакт про взаємодопомогу",
  "tour.idea.1991.1": "Виступити по телебаченню зі зверненням до народу щодо подій у Москві",
  "tour.idea.1991.2": "Наказати армії та міліції залишатися в казармах",
  "tour.idea.1991.3": "Попросити в західних урядів і МВФ кредити та визнання",
  "tour.idea.2014.1": "Скликати раду безпеки щодо кризи в Україні й вирішити, чого ми від неї хочемо",
  "tour.idea.2014.2": "Прощупати Москву, Брюссель і Вашингтон: хто на що готовий",
  "tour.idea.2014.3": "Наказати поліції тримати протести в країні мирними, без застосування сили",
  "tour.idea.2022.1": "Скликати раду безпеки щодо війни в Україні й визначити нашу лінію",
  "tour.idea.2022.2": "Забезпечити газ і нафту на прийдешню зиму",
  "tour.idea.2022.3": "Запитати союзників, яку допомогу вони готові дати й якою ціною",
  "tour.idea.1950.1": "Скликати екстрене засідання Ради Безпеки ООН щодо нападу в Кореї",
  "tour.idea.1950.2": "Привести армію та флот на Тихому океані в готовність і вирішити, чи посилати їх",
  "tour.idea.1950.3": "Таємно спитати Москву й Пекін, що вони зроблять, якщо Корея спалахне",
  "tour.idea.1964.1": "Відповісти на напад у Тонкінській затоці: удар, резолюція Конгресу чи стриманість",
  "tour.idea.1964.2": "Через нейтральний канал спитати Ханой, за яких умов він зупинить війну",
  "tour.idea.1964.3": "Зміцнити уряд у Сайгоні – або підшукати інший",
