  "tour.idea.1999.2": "Відрядити посланця до Белграда й до НАТО з мирним планом",
  "tour.idea.1999.3": "Підготуватися до біженців із Косова: табори, допомога, кордони",
  "tutorial.preparing": "Готуємо вашу першу партію…",
  "tutorial.failed": "Не вдалося підготувати навчання.",
  "tutorial.begin": "Почати навчання",
  "tutorial.replay": "Пройти навчання",
  "tutorial.note": "Навчання: перші два тижні написано заздалегідь, акаунт для них не потрібен.",
  "guide.skip": "Пропустити навчання",
  "guide.use": "Узяти це",
  "guide.doIt": "Зробіть це, і підказка піде далі.",
  "guide.waiting": "Ведучий пише тиждень…",
  "guide.welcome.title": "Ви ведете Україну",
  "guide.welcome.body": "Це навчання. Кожна картка просить зробити одну справу й іде далі, коли ви її зробили. Для перших двох тижнів акаунт не потрібен.",
  "guide.welcome.go": "Почати",
  "guide.map.title": "Мапа",
  "guide.map.body": "Україну намальовано своїм кольором, Росію – своїм. Штрихування – земля, яку тримає не її власник, смугаста область – та, за яку тривають бої, а товстий кордон між тими, хто тримає землю, – це фронт. Натисніть на країну чи область, щоб її роздивитися.",
  "guide.order.title": "Ваш перший наказ",
  "guide.order.body": "Напишіть простими словами, що ваш уряд робить цього ходу, – ведучий вирішить, що з того вийде. Візьміть цей наказ або напишіть свій, потім натисніть «Додати наказ».",
  "guide.end.title": "Завершіть хід",
  "guide.end.body": "Хід тут – один тиждень. Натисніть «Завершити хід»: тиждень буде зіграно, і відкриється звіт.",
  "guide.report.title": "Звіт",
  "guide.report.body": "Спершу – історія тижня, потім вердикт щодо кожного наказу: виконано, виконано частково чи провалено, – і що змінилося. Прочитавши, поверніться до гри.",
  "guide.front.title": "Фронт зрушив",
  "guide.front.body": "Зміни тижня підсвічено на мапі: росіяни просунулися на півночі, сході й півдні. Смуга вгорі показує ваші гроші, армію й настрій у країні.",
  "guide.cabinet.title": "Ваш кабінет",
  "guide.cabinet.body": "Міністри радять вам і роблять роботу. Відкрийте кабінет.",
  "guide.ask.title": "Запитайте міністра",
  "guide.ask.body": "Оберіть міністра й запитайте будь-що. Наприклад, запитайте головнокомандувача:",
  "guide.army.title": "Армія",
  "guide.army.body": "Солдати, зброя і де вони воюють. Відкрийте армію.",
  "guide.economy.title": "Економіка",
  "guide.economy.body": "Бюджет, ресурси й торгівля, на які йде війна. Відкрийте економіку.",
  "guide.letter.title": "Напишіть уряду",
  "guide.letter.body": "Листи можна писати будь-якому уряду, і кожен відповідає своїм голосом. Напишіть, наприклад, Польщі:",
  "guide.free.title": "Тепер грайте самі",
  "guide.free.body": "Ось і вся гра: накази, хід, звіт, міністри й світ. Ще один тиждень написано заздалегідь: віддайте будь-які накази й завершіть хід. Наприклад:",
  "guide.free.go": "Грати далі",
  "guide.choose.title": "Хто тепер грає світ?",
  "guide.choose.body": "Написані тижні скінчилися. Увійдіть через ChatGPT, щоб грав справжній ведучий на вашій підписці, або грайте далі з офлайн-ведучим.",
  "guide.choose.demo": "Грати офлайн",
  "guide.choose.demoNote": "Спрощено: світ грає офлайн-заглушка, і насправді майже нічого не змінюється.",
  "guide.done.title": "Ви готові",
  "guide.done.chatgpt": "Далі світ грає справжній ведучий на вашій підписці ChatGPT. Успіху.",
  "guide.done.demo": "Далі грає офлайн-ведучий: спрощено, але щоб освоїтися, вистачить. Увійти через ChatGPT можна в налаштуваннях будь-коли.",
  "guide.finish": "Завершити навчання",
  "state.quick.1": "Хочу перейменувати країну. Обговорімо назву.",
  "state.quick.2": "Яке місто заслуговує на нове ім'я і як це сприймуть люди?",
  "state.quick.3": "Який закон зараз найбільше нам заважає? Підготуй зміну.",
  "law.conscription.about": "Хто служить в армії: добровольці за контрактом, частина призовників щороку чи всі. Що ширший призов, то більша армія – і невдоволення.",
  "law.martial.about": "Звичайний режим, надзвичайний чи воєнний стан: наскільки влада може обмежувати права, вилучати майно й правити наказами.",
